<script setup lang="ts">
import DecimalInput from '@/components/shared/DecimalInput.vue'
import { formatPhone } from '@/lib/phone'
import { ref, reactive } from 'vue'
import { Plus, Trash2, X } from '@lucide/vue'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import ListPagination from '@/components/shared/ListPagination.vue'
import { useConfirm } from '@/composables/useConfirm'
import type { CvContent } from '@/lib/api'
const content = defineModel<CvContent>({ required: true })
const skill = ref('')
const section = ref('personal')
const tabs = [{id:'personal',label:'Personal'}, {id:'skills',label:'Skills'}, {id:'experience',label:'Experience'}, {id:'projects',label:'Projects'}, {id:'education',label:'Education'}, {id:'certifications',label:'Certificates'}, {id:'assessments',label:'Assessments'}, {id:'additional',label:'Additional'}]
const pages = reactive<Record<string,number>>({experience:1,projects:1,education:1,certifications:1,assessments:1})
const { confirmAction } = useConfirm()
function visible<T>(rows:T[], key:string) { return rows.map((entry,index)=>({entry,index})).slice(((pages[key]??1)-1)*2,(pages[key]??1)*2) }
function added(key:string, length:number) { pages[key] = Math.ceil(length/2) }
async function removeEntry(key:'experience'|'projects'|'education'|'certifications'|'assessments', index:number) {
  if (!await confirmAction({title:'Remove this CV entry?',description:'This removes the entry from this draft. Your verified records stay available.',confirmLabel:'Remove entry',destructive:true})) return
  content.value[key].splice(index,1)
  pages[key] = Math.min(pages[key]??1,Math.max(1,Math.ceil(content.value[key].length/2)))
}
function focusSection(key:string) { section.value=key; pages[key]=1 }
defineExpose({focusSection})
function addSkill() {
  const value = skill.value.trim()
  if (value && value.length <= 100 && content.value.skills.length < 50 && !content.value.skills.some(s => s.toLowerCase() === value.toLowerCase())) content.value.skills.push(value)
  skill.value = ''
}
</script>
<template>
  <div class="cv-editor space-y-5">
    <nav class="cv-section-tabs" aria-label="CV form sections"><button v-for="tab in tabs" :key="tab.id" type="button" :aria-pressed="section===tab.id" :class="{selected:section===tab.id}" @click="section=tab.id">{{ tab.label }}</button></nav>
    <p class="text-xs leading-5 text-muted-foreground">Choose a section to edit. Your draft is kept in this browser tab as you work.</p>
    <section v-show="section === 'personal'" class="cv-editor-section tone-card tone-blue"><h2>Make it yours.</h2><p>Check every detail. Only include information you can stand behind.</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label>Full name<Input v-model="content.personal.name" maxlength="120" autocomplete="name" /></label><label>Professional headline<Input v-model="content.personal.headline" maxlength="160" placeholder="e.g. Software engineering student" /></label><label>Email<Input v-model="content.personal.email" type="email" maxlength="255" /></label><label>Phone<Input v-model="content.personal.phone" type="tel" autocomplete="tel" maxlength="40" placeholder="+(60) - 123456789" @blur="content.personal.phone=formatPhone(content.personal.phone)" /></label><label>Location<Input v-model="content.personal.location" maxlength="120" /></label><label>Portfolio / LinkedIn<Input v-model="content.personal.website" maxlength="500" /></label></div><label class="mt-5 block">Professional summary<Textarea v-model="content.summary" rows="5" maxlength="3000" placeholder="What you do, the experience behind it, and where you want to go." /></label></section>
    <section v-show="section === 'skills'" class="cv-editor-section tone-card tone-blue"><h2>Skills</h2><p>List the skills you can explain and demonstrate.</p><div class="my-4 flex flex-wrap gap-2"><span v-for="(item,index) in content.skills" :key="index" class="inline-flex items-center gap-1 rounded-lg bg-accent pl-3 text-xs text-primary">{{ item }}<button type="button" class="grid size-9 place-items-center" :aria-label="'Remove '+item" @click="content.skills.splice(index,1)"><X class="size-3" /></button></span></div><div class="flex gap-2"><Input v-model="skill" aria-label="Add a skill" placeholder="Add a skill" maxlength="100" @keydown.enter.prevent="addSkill" /><Button type="button" variant="outline" :disabled="!skill.trim()" @click="addSkill"><Plus class="size-4" />Add</Button></div></section>
    <section v-show="section === 'experience'" class="cv-editor-section tone-card tone-blue"><div class="flex items-center justify-between gap-3"><h2>Work experience</h2><Button type="button" size="sm" variant="outline" @click="content.experience.push({role:'',company:'',period:'',description:''}); added('experience',content.experience.length)"><Plus class="size-4" />Add</Button></div><p>Internships, part-time roles and employment.</p><div v-for="{entry,index} in visible(content.experience, 'experience')" :key="index" class="cv-entry"><div class="flex items-center justify-between"><h3>Experience {{ index+1 }}</h3><Button type="button" size="icon-sm" variant="ghost" :aria-label="'Remove experience '+(index+1)" @click="removeEntry('experience',index)"><Trash2 class="size-4" /></Button></div><label>Role<Input v-model="entry.role" maxlength="255" /></label><div class="grid gap-3 sm:grid-cols-2"><label>Organisation<Input v-model="entry.company" maxlength="255" /></label><label>Period<Input v-model="entry.period" maxlength="100" placeholder="e.g. June – August 2026" /></label></div><label>Your contribution and outcome<Textarea v-model="entry.description" rows="4" maxlength="2000" /></label></div><p v-if="!content.experience.length" class="mt-4 text-xs">No work experience yet? Show what you have built in Projects below.</p><ListPagination v-model:page="pages.experience" :total="content.experience.length" :page-size="2" label="entries" /></section>
    <section v-show="section === 'projects'" class="cv-editor-section tone-card tone-blue"><div class="flex items-center justify-between gap-3"><h2>Projects</h2><Button type="button" size="sm" variant="outline" @click="content.projects.push({title:'',description:'',technologies:[]}); added('projects',content.projects.length)"><Plus class="size-4" />Add</Button></div><div v-for="{entry,index} in visible(content.projects, 'projects')" :key="index" class="cv-entry"><div class="flex items-center justify-between"><h3>Project {{ index+1 }}</h3><Button type="button" size="icon-sm" variant="ghost" :aria-label="'Remove project '+(index+1)" @click="removeEntry('projects',index)"><Trash2 class="size-4" /></Button></div><label>Project title<Input v-model="entry.title" maxlength="255" /></label><label>Your contribution and outcome<Textarea v-model="entry.description" rows="4" maxlength="2000" /></label><label>Technologies, separated by commas<Input :model-value="entry.technologies.join(', ')" @change="entry.technologies = ($event.target as HTMLInputElement).value.split(',').map(s=>s.trim()).filter(Boolean)" /></label></div><p v-if="!content.projects.length" class="mt-4 text-xs">Add a project that demonstrates your skills.</p><ListPagination v-model:page="pages.projects" :total="content.projects.length" :page-size="2" label="entries" /></section>
    <section v-show="section === 'education'" class="cv-editor-section tone-card tone-blue"><div class="flex items-center justify-between gap-3"><h2>Education</h2><Button type="button" size="sm" variant="outline" @click="content.education.push({institution:'',qualification:'',period:''}); added('education',content.education.length)"><Plus class="size-4" />Add</Button></div><div v-for="{entry,index} in visible(content.education, 'education')" :key="index" class="cv-entry"><div class="flex items-center justify-between"><h3>Education {{ index+1 }}</h3><Button type="button" size="icon-sm" variant="ghost" :aria-label="'Remove education '+(index+1)" @click="removeEntry('education',index)"><Trash2 class="size-4" /></Button></div><label>Institution<Input v-model="entry.institution" maxlength="255" /></label><label>Qualification<Input v-model="entry.qualification" maxlength="255" /></label><label>Period<Input v-model="entry.period" maxlength="100" /></label><label>Grades or honours<Textarea v-model="entry.details" maxlength="2000" placeholder="Include only details from your record" /></label></div><ListPagination v-model:page="pages.education" :total="content.education.length" :page-size="2" label="entries" /></section>
    <section v-show="section === 'certifications'" class="cv-editor-section tone-card tone-blue"><div class="flex items-center justify-between gap-3"><h2>Certifications</h2><Button type="button" size="sm" variant="outline" @click="content.certifications.push({title:'',issuer:'',issueDate:''}); added('certifications',content.certifications.length)"><Plus class="size-4" />Add</Button></div><div v-for="{entry,index} in visible(content.certifications, 'certifications')" :key="index" class="cv-entry"><div class="flex items-center justify-between"><h3>Certification {{ index+1 }}</h3><Button type="button" size="icon-sm" variant="ghost" :aria-label="'Remove certification '+(index+1)" @click="removeEntry('certifications',index)"><Trash2 class="size-4" /></Button></div><label>Title<Input v-model="entry.title" maxlength="255" /></label><label>Issuer<Input v-model="entry.issuer" maxlength="255" /></label><label>Issue date<Input v-model="entry.issueDate" maxlength="40" /></label></div><ListPagination v-model:page="pages.certifications" :total="content.certifications.length" :page-size="2" label="entries" /></section>
    <section v-show="section === 'assessments'" class="cv-editor-section tone-card tone-blue"><h2>Assessments</h2><p>Results from your skills record.</p><div v-for="{entry,index} in visible(content.assessments, 'assessments')" :key="index" class="cv-entry"><label>Assessment<Input v-model="entry.title" maxlength="255" /></label><div class="grid grid-cols-2 gap-3"><label>Score (%)<DecimalInput v-model="entry.percentage" min="0" max="100" /></label><label>Completed<Input v-model="entry.completedAt" maxlength="40" /></label></div><Button type="button" variant="ghost" size="sm" @click="removeEntry('assessments',index)">Remove result</Button></div><ListPagination v-model:page="pages.assessments" :total="content.assessments.length" :page-size="2" label="entries" /></section>
    <section v-show="section === 'additional'" class="cv-editor-section tone-card tone-blue"><h2>Anything else?</h2><p>Languages, awards, volunteering or other relevant details.</p><label class="mt-4 block">Additional information<Textarea v-model="content.additional" rows="6" maxlength="22000" /></label></section>
  </div>
</template>
<style scoped>
.cv-section-tabs{display:flex;flex-wrap:wrap;gap:6px;padding:8px;border:1px solid var(--border);border-radius:14px;background:var(--card)}.cv-section-tabs button{min-height:40px;padding:8px 12px;border-radius:9px;font-size:12px;color:var(--muted-foreground)}.cv-section-tabs button.selected{background:var(--primary);color:var(--primary-foreground);font-weight:600}.cv-section-tabs button:focus-visible{outline:2px solid var(--primary);outline-offset:2px}.cv-editor-section{border:1px solid var(--border);border-radius:16px;background:var(--tone-surface);border-color:var(--tone-border);padding:24px}.cv-editor-section h2{font-size:19px;font-weight:500}.cv-editor-section>p{margin-top:7px;color:var(--muted-foreground);font-size:12px;line-height:1.7}.cv-editor label{display:block;font-size:12px;font-weight:500}.cv-editor label :deep(input),.cv-editor label :deep(textarea){margin-top:7px;font-weight:400}.cv-entry{display:grid;gap:14px;margin-top:18px;padding-top:18px;border-top:1px solid var(--border)}.cv-entry h3{font-size:12px;color:var(--muted-foreground)}
</style>
